statement-execution-processor.statement:
declare
    V_CLOB CLOB;
begin
    DBMS_LOB.CREATETEMPORARY(V_CLOB, TRUE);
    DBMS_JAVA.export_resource({#1}, {#0}, V_CLOB);
    ? := V_CLOB;
end;

declare
    V_BLOB BLOB;
begin
    DBMS_LOB.CREATETEMPORARY(v_blob, TRUE);
    DBMS_JAVA.export_class({#1}, {#0}, v_blob);
    ? := V_BLOB;
end;

BEGIN
    DBMS_NETWORK_ACL_ADMIN.APPEND_HOST_ACE(
        host => {#1},
        ace => xs$ace_type(
            privilege_list => xs$name_list({#2}),
            principal_name => {#0},
            principal_type => xs_acl.ptype_db)
        );
END;

declare 
    v_line varchar2(32767);
    v_done number;
    v_report_clob CLOB;
begin
  dbms_lob.createtemporary(v_report_clob, TRUE, dbms_lob.call);
  loop
    exit when v_done = 1;
    dbms_output.get_line( v_line, v_done );
    dbms_lob.append(v_report_clob, TO_CLOB(v_line || chr(10)));
  end loop;
 :buffer := v_report_clob;
end;

select VALUE from (
    select VALUE from (
        select distinct {2} as VALUE from {0}.{1} where {2} is not null
    ) where rownum <= {3}
) order by VALUE

select count(DBMS_TRANSACTION.LOCAL_TRANSACTION_ID) as COUNT
  from DUAL
 where DBMS_TRANSACTION.LOCAL_TRANSACTION_ID is not null;
